619	async function loadStore(file: string): Promise<Store> {
620	  let text: string;
621	  try {
622	    text = await readFile(file, 'utf8');
623	  } catch (err) {
624	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore();
625	    throw new BizError(`无法读取数据文件 ${file}: ${(err as Error).message}`);
626	  }
627	  let raw: unknown;
628	  try {
629	    raw = JSON.parse(text);
630	  } catch (err) {
631	    throw new BizError(
632	      `数据文件 ${file} 已损坏，不是合法 JSON：${(err as Error).message}（原文件已保留，未当作空数据覆盖）`,
633	    );
634	  }
635	  return validateStore(raw, file);
636	}
