638	// 先完整写入临时文件，再原子改名；任何失败都不触碰原文件
639	async function saveStore(file: string, store: Store): Promise<void> {
640	  let json: string;
641	  try {
642	    json = JSON.stringify(store, null, 2) + '\n';
643	  } catch (err) {
644	    throw new BizError(`序列化数据失败：${(err as Error).message}（原文件已保留）`);
645	  }
646	  const tmp = `${file}.${process.pid}.tmp`;
647	  try {
648	    await writeFile(tmp, json, {encoding: 'utf8', flag: 'wx'});
649	    await rename(tmp, file);
650	  } catch (err) {
651	    await unlink(tmp).catch(() => {});
652	    throw new BizError(`保存数据文件 ${file} 失败：${(err as Error).message}（原文件已保留）`);
653	  }
654	}
