689	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
690	  return mergeIntervals(
691	    r.open.map(
692	      ([s, e]) =>
693	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
694	    ),
695	  );
696	}
697	
698	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
699	function subtractSegments(
700	  segments: Array<[number, number]>,
701	  cuts: Array<[number, number]>,
702	): Array<[number, number]> {
703	  let result = segments;
704	  for (const [cs, ce] of mergeIntervals(cuts)) {
705	    const next: Array<[number, number]> = [];
706	    for (const [s, e] of result) {
707	      if (ce <= s || e <= cs) {
708	        next.push([s, e]);
709	        continue;
710	      }
711	      if (s < cs) next.push([s, cs]);
712	      if (ce < e) next.push([ce, e]);
713	    }
714	    result = next;
715	  }
716	  return result;
717	}
718	
719	// 某资源的有效停用记录（按开始时间、标识排序）
720	function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
721	  return store.closures
722	    .filter((c) => c.resourceId === resourceId && c.status === 'active')
723	    .sort(
724	      (a, b) =>
725	        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
726	        a.id.localeCompare(b.id),
727	    );
728	}
729	
730	// 实际可用时间：原开放区间合并后，扣除该资源全部有效停用区间的并集（原开放记录保留）
731	function availableSegmentsOf(store: Store, r: ResourceRec): Array<[number, number]> {
732	  const cuts = activeClosuresOf(store, r.id).map(
733	    (c) =>
734	      [parseDateTime(c.start, '停用开始时间'), parseDateTime(c.end, '停用结束时间')] as [number, number],
735	  );
736	  return subtractSegments(openSegmentsOf(r), cuts);
737	}
