789	interface Conflict {
790	  booking: BookingRec;
791	  shared: string[];
792	}
793	
794	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
795	function findConflicts(
796	  store: Store,
797	  ids: string[],
798	  startMin: number,
799	  endMin: number,
800	  excludeBookingId?: string,
801	): Conflict[] {
802	  const wanted = new Set(ids);
803	  const conflicts: Conflict[] = [];
804	  for (const b of store.bookings) {
805	    if (b.status !== 'active') continue;
806	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
807	    const bStart = parseDateTime(b.start, '预约开始时间');
808	    const bEnd = parseDateTime(b.end, '预约结束时间');
809	    const overlap = bStart < endMin && startMin < bEnd;
810	    if (!overlap) continue;
811	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
812	    if (shared.length > 0) conflicts.push({booking: b, shared});
813	  }
814	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
815	  return conflicts;
816	}
817	
818	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
819	  if (conflicts.length === 0) return;
820	  const lines = conflicts.map(
821	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
822	  );
823	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
824	}
