836	function splitGlobalArgs(argv: string[]): GlobalArgs {
837	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
838	  for (let i = 0; i < argv.length; i++) {
839	    const a = argv[i];
840	    if (a === '-h' || a === '--help') {
841	      result.help = true;
842	    } else if (a === '--data') {
843	      const v = argv[++i];
844	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
845	      result.dataFile = v;
846	    } else if (a.startsWith('--data=')) {
847	      result.dataFile = a.slice('--data='.length);
848	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
849	    } else {
850	      result.rest.push(a);
851	    }
852	  }
853	  return result;
854	}
