1029	  }
1030	
1031	  let ids: string[] = booking.resourceIds;
1032	  if (hasResource) {
1033	    const resourceArgs = values.get('resource')!;
1034	    ids = resolveResourceIds(store, resourceArgs);
1035	  }
1036	
1037	  assertOpenCoverage(store, ids, startMin, endMin);
1038	  // 改期检查排除自身
