1089	// 清单结构（与数据文件无关的纯类型校验）；返回逐项原始记录
1090	function parseManifestShape(raw: unknown, file: string): Array<Record<string, unknown>> {
1091	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
1092	    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
1093	  }
1094	  const o = raw as Record<string, unknown>;
1095	  for (const k of Object.keys(o)) {
1096	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
1097	  }
1098	  if (!Array.isArray(o.items)) {
1099	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
1100	  }
1101	  const items = o.items as unknown[];
1102	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期安排`);
1103	
1104	  const problems: string[] = [];
1105	  const records: Array<Record<string, unknown> | null> = [];
1106	  items.forEach((it, idx) => {
1107	    const at = `第 ${idx + 1} 项`;
1108	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
1109	      problems.push(`${at} 必须是对象`);
1110	      records.push(null);
1111	      return;
1112	    }
1113	    const rec = it as Record<string, unknown>;
1114	    for (const k of Object.keys(rec)) {
1115	      if (k !== 'bookingId' && k !== 'start' && k !== 'end' && k !== 'resourceIds') {
1116	        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、start、end、resourceIds）`);
1117	      }
1118	    }
1119	    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
1120	      problems.push(`${at} 的 bookingId 必须是非空字符串`);
1121	    }
1122	    if (typeof rec.start !== 'string' || rec.start === '') {
1123	      problems.push(`${at} 的 start 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1124	    }
1125	    if (typeof rec.end !== 'string' || rec.end === '') {
1126	      problems.push(`${at} 的 end 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1127	    }
1128	    if (!Array.isArray(rec.resourceIds)) {
1129	      problems.push(`${at} 的 resourceIds 必须是非空数组（完整目标资源集合，整体替换原集合）`);
1130	    } else {
1131	      if (rec.resourceIds.length === 0) problems.push(`${at} 的 resourceIds 不能为空：资源集合整体替换，至少一个资源`);
1132	      rec.resourceIds.forEach((rid, j) => {
1133	        if (typeof rid !== 'string' || rid === '') {
1134	          problems.push(`${at}.resourceIds[${j}] 必须是非空资源标识字符串`);
1135	        }
1136	      });
1137	    }
1138	    records.push(rec);
1139	  });
1140	  if (problems.length > 0) {
1141	    throw new BizError(`改期清单 ${file} 内容非法，整批拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1142	  }
1143	  return records as Array<Record<string, unknown>>;
1144	}
