1146	async function cmdRescheduleBatch(args: string[]): Promise<void> {
1147	  const {values, positionals} = parseFlags(args, []);
1148	  if (values.size > 0) {
1149	    throw new UsageError(
1150	      `reschedule-batch 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
1151	    );
1152	  }
1153	  if (positionals.length !== 1) {
1154	    throw new UsageError('用法: reschedule-batch <改期清单文件>');
1155	  }
1156	  const manifestFile = positionals[0];
1157	
1158	  const file = activeDataFile;
1159	  const store = await loadStore(file);
1160	  const records = parseManifestShape(await loadManifest(manifestFile), manifestFile);
1161	
1162	  // 第一阶段：逐项做与业务数据相关的基础校验，收集全部问题后一次性拒绝整批
1163	  const problems: string[] = [];
1164	  const seenBooking = new Map<string, number>(); // 标识 -> 首次出现的序号（1 基）
1165	  const planned: Array<BatchTarget | null> = [];
1166	  records.forEach((rec, idx) => {
1167	    const at = `第 ${idx + 1} 项（${rec.bookingId as string}）`;
1168	    let ok = true;
1169	
1170	    const firstAt = seenBooking.get(rec.bookingId as string);
1171	    if (firstAt !== undefined) {
1172	      problems.push(`${at} 预约标识重复：该标识已在第 ${firstAt} 项出现，每项预约在清单中只能出现一次`);
1173	      ok = false;
1174	    } else {
1175	      seenBooking.set(rec.bookingId as string, idx + 1);
1176	    }
1177	
1178	    const booking = store.bookings.find((b) => b.id === rec.bookingId);
1179	    if (!booking) {
1180	      problems.push(`${at} 未知预约标识: ${rec.bookingId}`);
1181	      ok = false;
1182	    } else if (booking.status === 'cancelled') {
1183	      problems.push(`${at} 预约 ${booking.id} 已取消，不能改期`);
1184	      ok = false;
1185	    }
1186	
1187	    const rawRids = rec.resourceIds as string[];
1188	    const dupes = rawRids.filter((id, j) => rawRids.indexOf(id) !== j);
1189	    if (dupes.length > 0) problems.push(`${at} 资源重复指定: ${[...new Set(dupes)].join('、')}`);
1190	    const unknown = [...new Set(rawRids)]
1191	      .filter((id) => !store.resources.some((r) => r.id === id))
1192	      .sort();
1193	    if (unknown.length > 0) problems.push(`${at} 未知资源标识: ${unknown.join('、')}`);
1194	
1195	    let startMin = 0;
1196	    let endMin = 0;
1197	    let startParsed = false;
1198	    let endParsed = false;
1199	    try {
1200	      startMin = parseDateTime(rec.start as string, `${at} 目标开始时间`);
1201	      startParsed = true;
1202	    } catch (err) {
1203	      problems.push((err as BizError).message);
1204	    }
1205	    try {
1206	      endMin = parseDateTime(rec.end as string, `${at} 目标结束时间`);
1207	      endParsed = true;
1208	    } catch (err) {
1209	      problems.push((err as BizError).message);
1210	    }
1211	    if (startParsed && endParsed && endMin <= startMin) {
1212	      problems.push(
1213	        `${at} 目标结束时间必须晚于开始时间（开始: ${rec.start}，结束: ${rec.end}），允许跨日`,
1214	      );
1215	      ok = false;
1216	    }
1217	
1218	    if (!ok || !booking) {
1219	      planned.push(null);
1220	      return;
1221	    }
1222	    planned.push({
1223	      index: idx,
1224	      booking,
1225	      startRaw: rec.start as string,
1226	      endRaw: rec.end as string,
1227	      startMin,
1228	      endMin,
1229	      resourceIds: [...new Set(rawRids)].sort(),
1230	    });
1231	  });
1232	
1233	  if (problems.length > 0) {
1234	    throw new BizError(`改期清单 ${manifestFile} 校验失败，整批拒绝（原有安排保持不变）：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1235	  }
1236	  const targets = planned as BatchTarget[];
1237	  const batchIds = new Set(targets.map((t) => t.booking.id));
1238	
1239	  // 第二阶段：对“整批完成后”的安排做校验。
1240	  // 本批预约的旧占用一律不视为障碍（findConflicts 排除本批全部标识）；
1241	  // 障碍只来自本批之外的有效预约，以及本批各项的目标安排彼此之间。
1242	  const failures: BatchFailure[] = [];
1243	  for (const t of targets) {
1244	    const gaps = findCoverageGaps(store, t.resourceIds, t.startMin, t.endMin);
1245	    const external = findConflicts(store, t.resourceIds, t.startMin, t.endMin).filter(
1246	      (c) => !batchIds.has(c.booking.id),
1247	    );
1248	    const wanted = new Set(t.resourceIds);
1249	    const internal: BatchFailure['internal'] = [];
1250	    for (const o of targets) {
1251	      if (o.index === t.index) continue;
1252	      const overlap = o.startMin < t.endMin && t.startMin < o.endMin;
1253	      if (!overlap) continue;
1254	      const shared = o.resourceIds.filter((id) => wanted.has(id)).sort();
1255	      if (shared.length > 0) internal.push({other: o, shared});
1256	    }
1257	    if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
1258	      failures.push({target: t, gaps, external, internal});
1259	    }
1260	  }
1261	
1262	  if (failures.length > 0) {
1263	    // 按清单顺序报告全部不满足条件的项；批内冲突在双方项中都会出现
1264	    const blocks = failures.map(({target: t, gaps, external, internal}) => {
1265	      const lines = [`第 ${t.index + 1} 项 ${t.booking.id} 目标 ${t.startRaw} → ${t.endRaw}：`];
1266	      if (gaps.length > 0) {
1267	        lines.push('  开放不足资源:');
1268	        lines.push(...gapLines(gaps, '    '));
1269	      }
1270	      if (external.length + internal.length > 0) {
1271	        lines.push('  冲突预约:');
1272	        for (const c of external) {
1273	          lines.push(
1274	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
1275	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
1276	          );
1277	        }
1278	        for (const x of internal) {
1279	          lines.push(
1280	            `    - ${x.other.booking.id}（本批第 ${x.other.index + 1} 项目标 ${x.other.startRaw} → ${x.other.endRaw}）` +
1281	              `：共同资源 ${formatResourceIds(store, x.shared)}`,
1282	          );
1283	        }
1284	      }
1285	      return lines.join('\n');
1286	    });
1287	    throw new BizError(
1288	      `批量改期失败：共 ${failures.length} 项不满足条件（按清单顺序），整批未改动：\n${blocks.join('\n')}`,
1289	    );
1290	  }
1291	
1292	  // 全部验证通过：一次性替换各项目标安排并原子落盘。
1293	  // 仅改时间与资源；标识、status、seriesId、标识计数全部不变，不创建任何预约或系列。
1294	  // 若保存失败，磁盘原文件保留；本进程亦以退出码 1 结束，不会报告成功。
1295	  const noChange = targets.every(
1296	    (t) =>
1297	      t.booking.start === t.startRaw &&
1298	      t.booking.end === t.endRaw &&
1299	      t.booking.resourceIds.length === t.resourceIds.length &&
1300	      t.booking.resourceIds.every((id, j) => id === t.resourceIds[j]),
1301	  );
1302	  if (noChange) {
1303	    // 幂等：提交的安排与现状完全一致时成功且不触碰数据文件
1304	    console.log(
1305	      `批量改期成功：共 ${targets.length} 项，安排均与现状一致，无业务变化（标识与系列归属不变，数据文件未改动）`,
1306	    );
1307	    for (const t of targets) {
1308	      console.log(`第 ${t.index + 1} 项 ${t.booking.id}: ${t.startRaw} → ${t.endRaw}`);
1309	    }
1310	    return;
1311	  }
1312	  for (const t of targets) {
1313	    t.booking.start = t.startRaw;
1314	    t.booking.end = t.endRaw;
1315	    t.booking.resourceIds = t.resourceIds;
1316	  }
