2032	async function cmdAddClosure(args: string[]): Promise<void> {
2033	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end']);
2034	  if (positionals.length > 0) throw new UsageError(`add-closure 不接受位置参数: ${positionals.join(' ')}`);
2035	
2036	  const resourceId = requireFlag(values, 'resource');
2037	  const startRaw = requireFlag(values, 'start');
2038	  const endRaw = requireFlag(values, 'end');
2039	
2040	  const file = activeDataFile;
2041	  const store = await loadStore(file);
2042	
2043	  const resource = store.resources.find((r) => r.id === resourceId);
2044	  if (!resource) throw new BizError(`未知资源标识: ${resourceId}`);
2045	
2046	  const startMin = parseDateTime(startRaw, '停用开始时间');
2047	  const endMin = parseDateTime(endRaw, '停用结束时间');
2048	  if (endMin <= startMin) {
2049	    throw new BizError(`停用结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
2050	  }
2051	
2052	  // 登记前检查该资源的全部有效预约（含系列成员与候补兑现预约；已取消不阻挡）。
2053	  // 区间左闭右开，端点相接不算重叠；有重叠即拒绝，不改期或取消任何预约。
2054	  const affected = store.bookings
2055	    .filter((b) => {
2056	      if (b.status !== 'active' || !b.resourceIds.includes(resourceId)) return false;
2057	      const bs = parseDateTime(b.start, '预约开始时间');
2058	      const be = parseDateTime(b.end, '预约结束时间');
2059	      return bs < endMin && startMin < be;
2060	    })
2061	    .sort((a, b) => a.id.localeCompare(b.id));
2062	  if (affected.length > 0) {
2063	    const lines = affected.map((b) => `- ${b.id}（${b.start} → ${b.end}）`);
2064	    throw new BizError(
2065	      `无法登记停用：资源 ${resourceId}（${resource.name}）在该区间存在有效预约` +
2066	        `（不自动改期或取消，请先处理）：\n${lines.join('\n')}`,
2067	    );
2068	  }
2069	
2070	  // 全部校验通过后才生成标识、改内存、落盘；相同内容再次登记也是另一记录
2071	  store.closureSeq += 1;
2072	  const id = `C${String(store.closureSeq).padStart(4, '0')}`;
2073	  store.closures.push({id, resourceId, start: startRaw, end: endRaw, status: 'active'});
2074	  store.closures.sort((a, b) => a.id.localeCompare(b.id));
2075	  await saveStore(file, store);
2076	  console.log(`已登记停用 ${id}`);
2077	  console.log(`  资源: ${resourceId}（${resource.name}）`);
2078	  console.log(`  时间: ${startRaw} → ${endRaw}`);
2079	  console.log('  该区间不再计入实际可用时间；取消停用请使用 cancel-closure。');
2080	}
