2110	  if (values.size > 0) {
2111	    throw new UsageError(`cancel-closure 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`);
2112	  }
2113	  if (positionals.length !== 1) throw new UsageError('用法: cancel-closure <停用标识>');
2114	  const id = positionals[0];
2115	  if (!/^C\d{4,}$/.test(id)) throw new BizError(`停用标识非法: ${id}`);
2116	
2117	  const file = activeDataFile;
2118	  const store = await loadStore(file);
2119	  const closure = store.closures.find((c) => c.id === id);
2120	  if (!closure) throw new BizError(`未知停用标识: ${id}`);
2121	  if (closure.status === 'cancelled') {
2122	    // 幂等：重复取消成功且不做任何改动
2123	    console.log(`停用 ${id} 已是取消状态，未做改动。`);
2124	    return;
2125	  }
2126	  // 仅使该记录失效并保留历史；其他重叠停用仍有效，不自动创建预约或处理候补
2127	  closure.status = 'cancelled';
2128	  await saveStore(file, store);
2129	  console.log(`已取消停用 ${id}（记录保留），该区间恢复可用（不超出原开放时间）。`);
2130	}
