    let seriesId: string | undefined;
    if (it.seriesId !== undefined) {
      if (typeof it.seriesId !== 'string' || !/^S\d{4,}$/.test(it.seriesId)) {
        bad(`${iat}.seriesId 非法: ${String(it.seriesId)}`);
      }
      if (!seriesIds.has(it.seriesId)) bad(`${iat} 引用了未知系列: ${it.seriesId}`);
